_url": "https://discovery.ucl.ac.uk/1570070/1/Friston_Active%20Inference%20Curiosity%20and%20Insight.pdf", "any_repository_has_fulltext": true}, "primary_location": {"id": "doi:10.1162/neco_a_00999", "doi": "https://doi.org/10.1162/neco_a_00999", "is_oa": false, "landing_page_url": "https://doi.org/10.1162/neco_a_00999", "pdf_url": null, "source": {"id": "https://openalex.org/S207023548", "display_name": "Neural Computation", "issn_l": "0899-7667", "issn": ["0899-7667", "1530-888X"], "is_oa": false, "is_in_doaj": false, "is_core": true, "listed_in": ["anvur-scientific", "ccf-b", "cwts-core", "dongbi-b", "doyens", "erih-plus", "jufo-3", "medline", "norway-2", "poland-140", "russia-white-list-1", "vabb-shw"], "host_organization": "https://openalex.org/P4310315718", "host_organization_name": "The MIT Press", "host_organization_lineage": ["https://openalex.org/P4310315718", "https://openalex.org/P4310316440"], "host_organization_lineage_names": ["The MIT Press", "Massachusetts Institute of Technology"], "type": "journal"}, "license": null, "license_id": null, "version": "publishedVersion", "is_accepted": true, "is_published": true, "raw_source_name": "Neural Computation", "raw_type": "journal-article"}, "abstract": "This article offers a formal account of curiosity and insight in terms of active (Bayesian) inference. It deals with the dual problem of inferring states of the world and learning its statistical structure. In contrast to current trends in machine learning (e.g., deep learning), we focus on how people attain insight and understanding using just a handful of observations, which are solicited through curious behavior. We use simulations of abstract rule learning and approximate Bayesian inference to show that minimizing (expected) variational free energy leads to active sampling of novel contingencies. This epistemic behavior closes explanatory gaps in generative models of the world, thereby reducing uncertainty and satisfying curiosity. We then move from epistemic learning to model selection or structure learning to show how abductive processes emerge when agents test plausible hypotheses about symmetries (i.e., invariances or rules) in their generative models. The ensuing Bayesian model reduction evinces mechanisms associated with sleep and has all the hallmarks of \"aha\" moments. This formulation moves toward a computational account of consciousness in the pre-Cartesian sense of sharable knowledge (i.e., con: \"together\"; scire: \"to know\")."}]", "excerpt_truncated": true, "source_sha256": "96cdfe81fe09b1f1f3dd34f1141e478d2894beafc29cc398e8fcc981dcd5ebf3", "verification_required": true, "topic_domain": "unassigned_problem", "evidence_role": "discovery", "host_tier": "discovery", "source_identity": null, "persistent_identifiers": ["doi:10.48550/arxiv.1802.10546", "doi:10.1162/neco_a_00999", "openalex:W2789073708", "arxiv:1802.10546"], "source_candidates": ["https://doi.org/10.48550/arxiv.1802.10546", "https://arxiv.org/pdf/1802.10546", "https://discovery.ucl.ac.uk/1570070/1/Friston_Active%20Inference%20Curiosity%20and%20Insight.pdf", "https://doi.org/10.1162/neco_a_00999"], "source_candidate_identities": {}}
